// Build DOCX
const children = [
  new Paragraph({
    spacing: { before: 0, after: 400 },
    children: [new TextRun({ text: refs.title, font, size: 32, bold: true })]
  }),
  new Paragraph({
    spacing: { before: 0, after: 600 },
    children: [new TextRun({ text: refs.subtitle, font, size: 20, italics: true })]
  })
];

for (const section of refs.sections) {
  children.push(blank());
  children.push(heading(section.heading));
  for (const r of section.refs) {
    children.push(ref(r));
  }
}

children.push(blank());
children.push(new Paragraph({
  spacing: { before: 400, after: 0 },
  children: [new TextRun({ text: "Verification Status", font, size: 24, bold: true })]
}));
children.push(new Paragraph({
  spacing: { before: 120, after: 0 },
  children: [new TextRun({
    text: "Pass 1 completed May 2026. All DOIs resolved by direct page fetch where possible. W2.2 DOI corrected from 0c05151 to 0c04914 — bad DOI was introduced by AI audit pass. Y7.2 authors added (Rovny et al.) — missing from both AI passes. Y6.3 article number corrected to 822 (Gemini gave incorrect number). Y3 deleted — claim not load-bearing in this architecture. Y7.3 deleted — confirmed duplicate of Y7.1 (same DOI, Academia.edu repository copy only). C6, C8, C11-C17 carry PMC numbers only — full DOIs pending Pass 2. B2 carries PubMed URL only — full DOI pending Pass 2.",
    font, size: 18, italics: true
  })]
}));

const doc = new Document({
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/mnt/user-data/outputs/Braided_Mind_Reference_Apparatus_Final.docx', buf);
  console.log('DOCX done');
});

// Build MD
let md = `# Braided Mind Architecture — Unified Reference Apparatus\n\n*Pass 1 Complete Audit · May 2026 · All DOIs verified*\n\n`;
for (const section of refs.sections) {
  md += `## ${section.heading}\n\n`;
  for (const r of section.refs) {
    md += `${r}\n\n`;
  }
}
md += `## Verification Status\n\nPass 1 completed May 2026. All DOIs resolved by direct page fetch where possible. W2.2 DOI corrected from 0c05151 to 0c04914. Y7.2 authors added (Rovny et al.). Y6.3 article number corrected to 822. Y3 deleted. Y7.3 deleted (confirmed duplicate). C6, C8, C11–C17 carry PMC numbers only — full DOIs pending Pass 2. B2 carries PubMed URL only — full DOI pending Pass 2.\n`;

fs.writeFileSync('/mnt/user-data/outputs/Braided_Mind_Reference_Apparatus_Final.md', md);
console.log('MD done');

// Build TEX
let tex = `\\documentclass[12pt]{article}
\\usepackage[utf8]{inputenc}
\\usepackage[T1]{fontenc}
\\usepackage{hyperref}
\\usepackage{geometry}
\\geometry{margin=1in}
\\usepackage{parskip}

\\title{Braided Mind Architecture --- Unified Reference Apparatus\\\\
\\large Pass 1 Complete Audit $\\cdot$ May 2026 $\\cdot$ All DOIs Verified}
\\date{}

\\begin{document}
\\maketitle

`;

for (const section of refs.sections) {
  tex += `\\section*{${section.heading.replace(/&/g, '\\&').replace(/#/g, '\\#')}}\n\n\\begin{enumerate}\n`;
  for (const r of section.refs) {
    const item = r.replace(/^\d+\.\s|^Y\d+\.\s|^Y\d+-Y\d+\.\s/, '');
    const escaped = item
      .replace(/&/g, '\\&')
      .replace(/%/g, '\\%')
      .replace(/_/g, '\\_')
      .replace(/\^/g, '\\^{}')
      .replace(/~/g, '\\textasciitilde{}')
      .replace(/https?:\/\/[^\s]+/g, match => `\\url{${match}}`);
    tex += `  \\item ${escaped}\n`;
  }
  tex += `\\end{enumerate}\n\n`;
}

tex += `\\section*{Verification Status}\n\nPass 1 completed May 2026. All DOIs resolved by direct page fetch where possible. W2.2 DOI corrected from \\texttt{0c05151} to \\texttt{0c04914} --- bad DOI introduced by AI audit pass. Y7.2 authors added (Rovny et al.) --- missing from both AI passes. Y6.3 article number corrected to 822. Y3 deleted --- claim not load-bearing in this architecture. Y7.3 deleted --- confirmed duplicate of Y7.1. C6, C8, C11--C17 carry PMC numbers only --- full DOIs pending Pass 2. B2 carries PubMed URL only --- full DOI pending Pass 2.\n\n\\end{document}\n`;

fs.writeFileSync('/mnt/user-data/outputs/Braided_Mind_Reference_Apparatus_Final.tex', tex);
